with kept as (select s.* from accounts s where exists (select 1 from transactions c where c.account_id = s.id and c.account_id in (20, 25, 28, 33))) select date_trunc('year', opened_date) as year_start, case when balance >= 85000 then 'HIGH' else 'LOW' end as balance_tier, approx_percentile(balance, array(0.25, 0.5, 0.75)) as balance_quartiles, size(collect_set(status)) as num_status from kept group by 1, 2 having size(collect_set(status)) >= 1;
